import heapq
from collections import Counter, defaultdict
from typing import List


class LionCompetition:
    def __init__(self, lions: List[dict], schedule: List[dict]):
        self.height = {l["name"]: l["height"] for l in lions}
        self.pending_enter = defaultdict(list)
        self.pending_exit = defaultdict(list)
        for s in schedule:
            h = self.height[s["name"]]
            self.pending_enter[(s["enterTime"], h)].append(s["name"])
            self.pending_exit[(s["exitTime"], h)].append(s["name"])
        self.ours = set()
        self.opp = Counter()
        self.heap = []  # max-heap of competitor heights (negated), lazy deletion

    def lionEntered(self, currentTime: int, height: int) -> None:
        mine = self.pending_enter.get((currentTime, height))
        if mine:
            self.ours.add(mine.pop())
        else:
            self.opp[height] += 1
            heapq.heappush(self.heap, -height)

    def lionLeft(self, currentTime: int, height: int) -> None:
        for name in self.pending_exit.get((currentTime, height), []):
            if name in self.ours:
                self.ours.remove(name)
                return
        self.opp[height] -= 1

    def getBiggestLions(self) -> List[str]:
        while self.heap and self.opp[-self.heap[0]] == 0:
            heapq.heappop(self.heap)
        best = -self.heap[0] if self.heap else float("-inf")
        return sorted(n for n in self.ours if self.height[n] >= best)
